"use server";

// Generated by philote from page /slots/new. Do not edit.
import { redirect } from "next/navigation";

import { slots } from "@/lib/api";
import { type FormState, dateTime, failed, text } from "@/lib/form";

export async function submit(_state: FormState, data: FormData): Promise<FormState> {
    const result = await slots.create({
        starts_at: dateTime(data, "starts_at"),
        service_id: text(data, "service_id"),
    });
    if (!result.ok) {
        return failed(data, result.error, result.issues);
    }
    redirect("/book");
}
